local M = class("CastingSwordTaskInfoView",LikeOO.OOPopBase)

M.m_uiName = "CastingSwordMeeting/CastingSwordTaskInfo"  -- prefab name
M.m_size_type = 2
M.m_iphoneXAdapter = true

function M:onEnter()
    self:setTextByLanKey("text_title", "zj_jliangli_text")
    self:setTextByLanKey("ServerBtnText", "castingSword_str_0052")
    self:setTextByLanKey("SelfBtnText", "castingSword_str_0053")
    self:refreshUI()
end

function M:refreshUI()
    self:createLoopScroll(self.m_model.m_allAwardsData)
end

function M:createLoopScroll(awardData)
    local data = awardData
    if self.m_scroll_view == nil then
        local loopscroll = self:findGameObject("loopscroll")
        local params ={
            show_data = data,
            loop_scroll_object = loopscroll,
            update_cell =function(index, cell_obj, cell_data)
                self:update_Gift(cell_obj, cell_data, index)
            end,
            click_func = function(index, cell_object, cell_data, click_object, click_name) -- 点击回调
                if click_name == "btn_canGotBtn" then
                    local params = {vsn = self.m_model.m_version, score_id = cell_data.id, type = cell_data.xlsxData.person}
                    self.m_model:getNetData("sword_recv_score_reward", params, function(response)
                        if response then
                            if self.m_control:activityOverExamine(response) then
                                return
                            end
                            RewardUtil:rewardTipsByData(response.reward)
                            if response.type == 1 then
                                self.m_model:setPersonScoreDone(response.score_done)
                            else
                                self.m_model:setScoreDone(response.score_done)
                            end
                            local luaBehaviour = UIUtil.findLuaBehaviour(cell_object)
                            if luaBehaviour then
                                LuaBehaviourUtil.setObjectVisible(luaBehaviour, "btn_canGotBtn", false)
                                LuaBehaviourUtil.setObjectVisible(luaBehaviour, "text_gotBtnText", true)
                            end
                            self:updateMsg("refresh_castingSwordGotAward", response)
                                end
                    end, nil, nil, nil)
                end
            end
        }
        self.m_scroll_view = LoopScrollViewUtil.new(params)
    else
        self.m_scroll_view:reloadData(data)
    end
end

function M:switchTab(msg)
    if msg == "ServerBtn" then
        self:createLoopScroll(self.m_model.m_allAwardsData)
        self:setImg( "a_ui_currency_yeqian_h_n" , "common_ui","ServerBtn")
        self:setImg( "a_ui_currency_yeqian_h_s" , "common_ui", "SelfBtn")
    else
        self:createLoopScroll(self.m_model.m_allPersonAwardsData)
        self:setImg(  "a_ui_currency_yeqian_h_s", "common_ui","ServerBtn")
        self:setImg(  "a_ui_currency_yeqian_h_n" , "common_ui", "SelfBtn")
    end

end
function M:update_Gift(cell_obj, cell_data, index)
    local luaBehaviour = UIUtil.findLuaBehaviour(cell_obj)
    if luaBehaviour then
        local xlsxData = cell_data.xlsxData
        local transform = cell_obj.transform

        local isGot = (self.m_model.m_score_done[cell_data.id] ~= nil)
        if xlsxData.person == 1 then
            isGot = (self.m_model.m_person_score_done[cell_data.id] ~= nil)
        end
        local isCanGot = (self.m_model.m_score >= xlsxData.score)
        if xlsxData.person == 1 then
            isCanGot = (self.m_model.m_self_score >= xlsxData.score)
        end
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "text_gotBtnText", isGot)
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_gotBtnText","castingSword_str_0005")
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "btn_canGotBtn", isCanGot and (not isGot))
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_canGotBtnText","castingSword_str_0014")
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_taskTitle",xlsxData.name)
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "text_unfinished", (not isCanGot))
        -- 奖励
        for i = 1, 3 do
            local awardData = xlsxData.reward or {}
            local reward_node = UIUtil.findRectTransform(transform, "awardNode"..i)
            UIUtil.destroyAllChild(reward_node)
            if awardData[i] then
                local itemNode = GameUtil:createItemElement(awardData[i], true, true)
                itemNode.transform:SetParent(reward_node.transform, false)
            end
        end
    end
end

function M:destroy()
    M.super.destroy(self)
end

return M